from taf.rfrl.l3_call.cell.classical_cell.classical_cell import ClassicalCell
from taf.rfrl.l3_call.cell.exceptions import CellIdNotFound, CellIsNotSuperCell
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_to_console
from taf.rfrl.l3_call.enviornment.exceptions import ParameterValueNotFound


class ClassicalNrCell(ClassicalCell):
    def __init__(self, cell_distname, bts_connection_alias, shared_spectrum):
        super(ClassicalNrCell, self).__init__(cell_distname, bts_connection_alias, shared_spectrum)
        self._type = "nr"

    def __str__(self):
        return "ClassicalNrCell cell instance for {0} cell type".format(self._type)

    def _is_beamforming_activated(self):
        self._load_scf()
        try:
            beamforming = self._scf.get_value_from_scf(dist_name=self.distname, p_name="actBeamforming")
        except KeyError:
            beamforming = False
        return True if beamforming == "True" else False

    def _get_beamforming_delay(self):
        """
        Based on 5G_RAN_RF_6104
        returns: beamforming delay in seconds
        """
        return 170

    def _make_callable(self, delta):
        log_to_console("Making cell {} callable".format(self.distname))
        if not self._check_blocking_state(expected_state="Unblocked"):
            self._unblock_cell()
            self._check_blocking_state(expected_state="Unblocked")

        if delta:
            log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
            delta.add_parameter_to_delta(dist_name=self.distname, parameter="cellBarred", value="notBarred")
        else:
            self._change_cellbarred_parameter(value="notBarred", cell_distname=self.distname)

    def _make_uncallable(self, delta):
        if self._shared_spectrum and not self._check_blocking_state(expected_state="Blocked"):
            log_to_console("Blocking cell {}".format(self.distname))
            self._block_cell()
            self._check_blocking_state(expected_state="Blocked")

        if not self._shared_spectrum and not self._check_blocking_state(expected_state="Blocked"):
            log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
            delta.add_parameter_to_delta(dist_name=self.distname, parameter="cellBarred", value="barred")

    def _make_barred(self, delta):
        log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
        delta.add_parameter_to_delta(dist_name=self.distname, parameter="cellBarred", value="barred")

    def _make_unbarred(self, delta):
        log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
        delta.add_parameter_to_delta(dist_name=self.distname, parameter="cellBarred", value="notBarred")

    def _get_dss_pair(self):
        dss_info = self._api.get_managed_objects(connection=self._connection,
                                                 class_name="NRDSSLTE_A")
        for nr_dss_lte in dss_info:
            if nr_dss_lte["distName"].split("/")[-2].split("-")[-1] == self._configuration_id:
                if nr_dss_lte["parameters"]["ltePhyCellId"]:
                    return self._get_configuration_distname_using_physical_cell_id(
                        physical_cell_id=nr_dss_lte["parameters"]["ltePhyCellId"], cell_type="lte")

    @log_input_and_output
    def _get_cell_id(self):
        cells_info = self._api.get_subcells_info(connection=self._connection)
        for cell_gr_name, cell_gr_info in cells_info.items():
            for cell_name, cell_info in cell_gr_info.items():
                if cell_name == self.distname.split("/")[-1]:
                    try:
                        return cell_info['NRCELL_R']['parameters']['nrCellIdentity']
                    except KeyError:
                        raise CellIdNotFound("Cell ID not found for cell {}".format(self.distname))

    def _get_number_of_super_subcells(self):
        for cell in self._api.get_cells_info(cell_type="nr", connection=self._connection):
            if cell["id"]["configuration"] == self.distname:
                try:
                    number_of_super_subcells = int(len(cell["subCellList"]) / 2)
                    return number_of_super_subcells
                except KeyError:
                    raise CellIsNotSuperCell("Seems like your cell is not supercell! Consider using different L3 call"
                                             " method from the interface e.g. L3 Call that can be used on regular cell"
                                             " or correct your configuration file.")

    def _get_carrier_frequency_and_channel_bandwidth(self, cells_info, cell_specific_info):
        nrarfcn = self._get_nrarfcn(cells_info=cells_info)
        carrier_frequency = self._calculate_carrier_frequency(nrarfcn=nrarfcn)
        channel_bandwidth = self._get_channel_bandwidth(cells_info=cells_info)

        return float(channel_bandwidth.replace("MHz", "")), int(carrier_frequency)

    def _get_nrarfcn(self, cells_info):
        try:
            nrarfcn = self._get_parameter_from_cells_info_for_nrcell(parameter="nrarfcnDl", cells_info=cells_info)
        except ParameterValueNotFound:
            nrarfcn = self._get_parameter_from_cells_info_for_nrcell(parameter="nrarfcn", cells_info=cells_info)
        return nrarfcn

    def _get_channel_bandwidth(self, cells_info):
        try:
            channel_bandwidth = self._get_parameter_from_cells_info_for_nrcell(parameter="chBwDl",
                                                                               cells_info=cells_info)
        except ParameterValueNotFound:
            channel_bandwidth = self._get_parameter_from_cells_info_for_nrcell(parameter="chBw",
                                                                               cells_info=cells_info)
        return channel_bandwidth

    def _get_parameter_from_cells_info_for_nrcell(self, parameter, cells_info):
        nr_cells_info = cells_info["nr"]
        try:
            for cell in nr_cells_info:
                if cell["id"]["configuration"] == self.distname:
                    return cell[parameter]

        except KeyError:
            raise ParameterValueNotFound("Could not find parameter {} for cell {}".format(parameter,
                                                                                          self.distname))

    @log_input_and_output
    def _calculate_carrier_frequency(self, nrarfcn):
        """
        Calculates carrier frequency using nrarfcn value. Calculator based on:
        https://www.etsi.org/deliver/etsi_ts/138100_138199/138104/16.04.00_60/ts_138104v160400p.pdf Chapter 5.4.2.1
        :param nrarfcn: NR-ARFCN
        :type nrarfcn: str or int
        :return: carrier frequency in MHz
        :rtype: float
        """
        if 0 <= int(nrarfcn) <= 599999:
            f_glob, f_ref_offs, n_ref_offs = 5, 0, 0
        elif 600000 <= int(nrarfcn) <= 2016666:
            f_glob, f_ref_offs, n_ref_offs = 15, 3000, 600000
        else:
            f_glob, f_ref_offs, n_ref_offs = 60, 24250.08, 2016667

        return f_ref_offs + f_glob * (int(nrarfcn) - n_ref_offs) * 10 ** -3

    @log_input_and_output
    def _get_protocol_for_pcap_verification(self):
        return "ngap"

    @log_input_and_output
    def _get_ok_msgs_and_procedure_codes(self):
        return {
            "InitialUEMessage": 15,
            "UERadioCapabilityInfoIndication": 44,
            "InitialContextSetupResponse": 14
        }

    @log_input_and_output
    def _get_nok_msgs_and_procedure_codes(self):
        return {
            "UEContextReleaseComplete": 41
        }

    @log_input_and_output
    def _get_nok_structures(self):
        return [
            {"ngap.UEContextReleaseCommand_element": {
                'ngap.protocolIEs_tree': {
                    'Item 1: id-Cause': {
                        'ngap.ProtocolIE_Field_element': {
                            'ngap.value_element': {
                                'ngap.Cause': "2",
                                'ngap.Cause_tree': {
                                    'ngap.nas': "2"
                                }
                            }
                        }
                    }
                }
            }
            },
            {"ngap.UEContextReleaseCommand_element": {
                'ngap.protocolIEs_tree': {
                    'Item 1: id-Cause': {
                        'ngap.ProtocolIE_Field_element': {
                            'ngap.value_element': {
                                'ngap.Cause': "0",
                                'ngap.Cause_tree': {
                                    'ngap.radioNetwork': "21"
                                }
                            }
                        }
                    }
                }
            }
            }
        ]
